      + `<div class="grid split">${ui.card({ flush: true, body: ui.table({ cols: [{ l: 'Client', v: (k) => { const c = cust(k.cid); return `<a href="#/customers/${c.id}"><b>${esc(T.fullName(c))}</b></a><div class="tiny faint">${esc(c.addr)}, ${esc(c.town)}</div>`; } }, { l: 'Service', v: (k) => `${esc(k.type)}<div class="tiny faint">${esc(k.freq)}</div>` }, { l: 'Price', r: 1, v: (k) => T.money(k.price) + (k.type === 'Mowing' ? '<span class="tiny faint"> / visit</span>' : '') }, { l: 'Season value', r: 1, v: (k) => `<b>${T.money(k.value)}</b>` }, { l: 'Status', v: (k) => ui.badge(k.status, stTone[k.status], true) }], rows: list.slice(0, 40) }) })}
        ${ui.card({ title: 'Next season renewals', sub: `${toRenew.length} lawn clients not renewed yet`, icon: 'refresh', tone: 'violet', flush: true, body: toRenew.slice(0, 9).map((c) => `<div class="li"><span class="grow"><a class="t1" style="display:block" href="#/customers/${c.id}">${esc(T.fullName(c))}</a><div class="t2">${esc(c.mow)} mowing · ${c.spring === 'Sent' ? 'reminder sent' : 'not contacted'}</div></span>${c.spring === 'Sent' ? ui.badge('Sent', 'violet') : `<button class="btn btn-xs" data-act="renewOne" data-id="${c.id}">Send</button>`}</div>`).join(''), foot: `<button class="btn btn-block" data-act="sendRenewals">${icon('send', 'sm')}Send to all ${toRenew.filter((c) => c.spring !== 'Sent').length} remaining</button>` })}</div>`;
