      + `<div class="grid g-2">${ui.card({ title: 'Line items', sub: 'Edit and the proposal updates live', icon: 'list', body: `<div id="estLines">${e.lines.map((l, i) => `<div class="line-edit"><input class="input" value="${esc(l.d)}" data-input="estLine" data-i="${i}" data-f="d" aria-label="Description"><input class="input" type="number" value="${l.q}" data-input="estLine" data-i="${i}" data-f="q" aria-label="Quantity"><input class="input" type="number" step="0.01" value="${l.p}" data-input="estLine" data-i="${i}" data-f="p" aria-label="Unit price"><b class="num lt" style="text-align:right">${T.money(l.q * l.p)}</b><button class="icon-btn" data-act="estDel" data-v="${i}" aria-label="Remove line">${icon('trash', 'sm')}</button></div>`).join('')}</div><div class="row mt-s"><button class="btn btn-sm" data-act="estAdd">${icon('plus', 'sm')}Add line</button><span class="spacer"></span><span class="muted">Total</span><b class="est-total" id="estTot">${T.money(estTotal(e))}</b></div>` })}
        <div><div class="estimate-doc" id="estDoc">${docHtml(e)}</div></div></div>`;
