      + ui.card({ flush: true, body: ui.table({ cols: [{ l: 'Date', v: (a) => `<b>${T.fmtDate(a.date)}</b><div class="tiny faint">${T.fmtTime(a.date)}</div>` }, { l: 'Property', v: (a) => { const c = cust(a.cid); return `<a href="#/customers/${c.id}">${esc(c.addr)}</a><div class="tiny faint">${esc(c.town)}</div>`; } }, { l: 'Product', v: (a) => `${esc(a.product)}<div class="tiny faint">${esc(a.rate)}</div>` }, { l: 'Area', r: 1, v: (a) => T.num(a.area) + ' sq ft' }, { l: 'Weather', v: (a) => `${a.temp}°F, wind ${a.wind} mph` }, { l: 'Re-entry', v: (a) => esc(a.rei) }, { l: 'Applicator', v: (a) => esc((T.byId(S().team, a.by) || {}).name || '') }], rows: L }) });
